import { View, Text, Pressable, StyleSheet } from "react-native";
import { useRef, useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const taps = useRef(0);
  const [shown, setShown] = useState(0);
  return (
    <View style={styles.s}>
      <Pressable nativeID="tap" style={styles.b} onPress={() => { taps.current = taps.current + 1; }}><Text style={styles.t}>Дарах</Text></Pressable>
      <Pressable nativeID="show" style={styles.b2} onPress={() => setShown(taps.current)}><Text style={styles.t2}>Харах</Text></Pressable>
      <Text nativeID="out" style={styles.o}>Нийт: {shown}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 14, padding: 24, alignItems: "center", justifyContent: "center" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 },
  b2: { backgroundColor: "#0ea5e9", padding: 14, borderRadius: 12 },
  t: { color: "#fff", fontWeight: "bold" }, t2: { color: "#fff", fontWeight: "bold" },
  o: { fontSize: 22, fontWeight: "bold" },
});

registerRootComponent(App);
